// Extract deal data and map pricing tier
const deal = $input.first().json;

const pricingField = deal.properties.pricing_tier || '';
const contactEmail = deal.properties.contact_email || '';
const contactName = deal.properties.contact_name || '';
const companyName = deal.properties.company_name || '';
const dealAmount = parseFloat(deal.properties.amount) || 0;

// Map pricing tiers to Xero line items
// CONFIGURE: Update these tiers to match your 3 pricing options
const tierMap = {
  'tier_1': {
    description: 'Service Package - Tier 1',
    unitAmount: 500,
    quantity: 1,
    accountCode: '200'
  },
  'tier_2': {
    description: 'Service Package - Tier 2',
    unitAmount: 1000,
    quantity: 1,
    accountCode: '200'
  },
  'tier_3': {
    description: 'Service Package - Tier 3',
    unitAmount: 2000,
    quantity: 1,
    accountCode: '200'
  }
};

const tier = tierMap[pricingField.toLowerCase().trim()];

if (!tier) {
  return [{ json: { error: true, message: `Unknown pricing tier: ${pricingField}`, dealId: deal.id } }];
}

return [{
  json: {
    error: false,
    contactEmail,
    contactName,
    companyName,
    dealId: deal.id,
    dealAmount,
    pricingTier: pricingField,
    lineItem: tier
  }
}];

// Log success back to HubSpot
const invoiceNumber = $input.first().json.Invoices?.[0]?.InvoiceNumber || 'unknown';
return [{ json: { note: `Xero invoice ${invoiceNumber} created automatically`, dealId: $('Map Pricing Tier').first().json.dealId } }];
